After installing (npm install multer), configuring Multer and handling a single-file upload route:

import multer from 'multer';

const upload = multer({ dest: 'uploads/' }); // files temporarily saved
                                                 // to this local folder

app.post('/profile/avatar', upload.single('avatar'), (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'No file provided' });
    }

    // req.file contains the uploaded file's metadata and temporary path
    // req.body contains any accompanying TEXT fields, exactly like a
    // normal JSON-equivalent body would
    res.json({
      success: true,
      data: { filename: req.file.filename, size: req.file.size }
    });
  } catch (err) {
    next(err);
  }
});

upload.single('avatar') specifically expects exactly ONE file, sent
under the form field name 'avatar' - this name must match exactly
what the frontend's form actually sends.

