  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'A photo is required' });
    }

    const { caption } = req.body; // the TEXT field, available here
                                     // ONLY because Multer has already
                                     // correctly parsed this multipart
                                     // request by this point

    if (!caption) {
      return res.status(400).json({ success: false, error: 'A caption is required' });
    }

    const post = await createPost({
      photoPath: req.file.path,
      caption
    });

    res.status(201).json({ success: true, data: post });
  } catch (err) {
    next(err);
  }
});

