After installing (npm install cloudinary) and configuring credentials (directly via environment variables, Module 10, lesson 6's exact discipline):

import { v2 as cloudinary } from 'cloudinary';

cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET
});

Uploading a file Multer has temporarily saved locally (lesson 1's exact output), then immediately moving it to Cloudinary's durable storage:

import multer from 'multer';
const upload = multer({ dest: 'uploads/' });

app.post('/profile/avatar', upload.single('avatar'), async (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'No file provided' });
    }

    const result = await cloudinary.uploader.upload(req.file.path, {
      folder: 'avatars'
    });

    // result.secure_url is the PERMANENT, durable URL - this is what
    // gets stored in your own database, not the temporary local path
    await usersCollection.updateOne(
      { _id: new ObjectId(req.userId) },
      { $set: { avatarUrl: result.secure_url } }
    );

    res.json({ success: true, data: { avatarUrl: result.secure_url } });
  } catch (err) {
    next(err);
  }
});

