// After uploading, Cloudinary's returned URL can be modified with
// transformation parameters to request DIFFERENT versions of the
// SAME underlying image, generated on-the-fly by Cloudinary itself

const originalUrl = 'https://res.cloudinary.com/demo/image/upload/v1234/avatars/photo.jpg';

// Inserting transformation parameters directly into the URL path
function getThumbnailUrl(originalUrl: string): string {
  return originalUrl.replace('/upload/', '/upload/w_150,h_150,c_fill/');
  // w_150,h_150 = resize to 150x150; c_fill = crop to fill that exact
  // size without distorting the image's proportions
}

function getMediumUrl(originalUrl: string): string {
  return originalUrl.replace('/upload/', '/upload/w_500,q_auto/');
  // w_500 = resize to 500px wide; q_auto = Cloudinary automatically
  // picks an optimal quality/file-size tradeoff for this specific image
}

// A single stored URL (avatarUrl) can now serve THREE genuinely
// different use cases - a small profile thumbnail, a medium preview,
// and the full original - all generated on-demand, with NO separate
// upload or separate file ever needing to be stored for each size
const thumbnailUrl = getThumbnailUrl(user.avatarUrl);
const mediumUrl = getMediumUrl(user.avatarUrl);

