Uploading a file (after Multer has saved it locally, lesson 1's pattern):

import fs from 'fs';

async function uploadToS3(localFilePath: string, key: string) {
  const fileContent = fs.readFileSync(localFilePath);

  await s3Client.send(new PutObjectCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: key, // the unique path/identifier within the bucket
    Body: fileContent,
    ContentType: 'application/pdf' // or whatever the actual file type is
  }));

  return `https://${process.env.S3_BUCKET_NAME}.s3.amazonaws.com/${key}`;
}

app.post('/documents', upload.single('document'), async (req, res, next) => {
  try {
    const key = `documents/${Date.now()}-${req.file.originalname}`;
    const url = await uploadToS3(req.file.path, key);
    res.json({ success: true, data: { url } });
  } catch (err) {
    next(err);
  }
});

