import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const s3Client = new S3Client({ region: process.env.AWS_REGION });

async function uploadInvoice(localFilePath: string, userId: string, invoiceId: string) {
  const key = `invoices/${userId}/${invoiceId}.pdf`; // a deliberate,
    // consistent structure: resourceType/ownerId/identifier, making
    // it straightforward to later list or reason about a specific
    // user's own invoices specifically

  await s3Client.send(new PutObjectCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: key,
    Body: fs.readFileSync(localFilePath),
    ContentType: 'application/pdf'
  }));

  return key; // STORE THE KEY in your own database, not a permanent
               // public URL - this file should only be accessible to
               // its specific owner, exactly Module 9's authorization
               // discipline applied to file access specifically
}

// Generating a TEMPORARY, time-limited URL specifically for the
// genuinely authorized owner to download their own invoice
app.get('/invoices/:id', requireAuth, async (req, res, next) => {
  try {
    const invoice = await invoicesCollection.findOne({ _id: new ObjectId(req.params.id) });

    if (invoice.userId.toString() !== req.userId) {
      return res.status(403).json({ success: false, error: 'Not authorized' });
    }

    const url = await getSignedUrl(
      s3Client,
      new GetObjectCommand({ Bucket: process.env.S3_BUCKET_NAME, Key: invoice.s3Key }),
      { expiresIn: 300 } // this specific URL expires in 5 minutes,
        // directly extending Module 9's token-expiration discipline
        // to file-access URLs specifically
    );

    res.json({ success: true, data: { downloadUrl: url } });
  } catch (err) {
    next(err);
  }
});

