After installing (npm install sharp), processing an uploaded image directly:

import sharp from 'sharp';

async function createThumbnail(inputPath: string, outputPath: string) {
  await sharp(inputPath)
    .resize(150, 150, { fit: 'cover' }) // resize to exactly 150x150,
                                           // cropping as needed to fill
                                           // that size without distortion
    .jpeg({ quality: 80 }) // convert to JPEG, compressed to 80% quality
    .toFile(outputPath);
}

async function optimizeForWeb(inputPath: string, outputPath: string) {
  await sharp(inputPath)
    .resize(1200, null, { withoutEnlargement: true }) // resize to max
      // 1200px wide, preserving aspect ratio, NEVER enlarging a
      // smaller original image beyond its genuine original size
    .webp({ quality: 85 }) // WebP - a modern, often smaller format
    .toFile(outputPath);
}

Applying this directly within an upload route, before sending the
processed result to S3 (lesson 3) for durable storage:

app.post('/products/:id/image', upload.single('image'), async (req, res, next) => {
  try {
    const thumbnailPath = `processed/thumb-${req.file.filename}.jpg`;
    await createThumbnail(req.file.path, thumbnailPath);

    const key = await uploadToS3(thumbnailPath, `products/${req.params.id}/thumb.jpg`);
    res.json({ success: true, data: { thumbnailKey: key } });
  } catch (err) {
    next(err);
  }
});

