import sharp from 'sharp';
import path from 'path';

interface ProcessedSizes {
  thumbnail: string;
  medium: string;
  original: string;
}

async function processUploadedImage(inputPath: string, outputDir: string, baseName: string): Promise<ProcessedSizes> {
  const thumbnailPath = path.join(outputDir, `${baseName}-thumb.jpg`);
  const mediumPath = path.join(outputDir, `${baseName}-medium.jpg`);
  const originalPath = path.join(outputDir, `${baseName}-original.jpg`);

  // Generate all three sizes from the SAME original input, exactly
  // mirroring lesson 2's single-upload-multiple-display-sizes pattern,
  // just performed manually here instead of via Cloudinary's URLs
  await Promise.all([
    sharp(inputPath).resize(150, 150, { fit: 'cover' }).jpeg({ quality: 80 }).toFile(thumbnailPath),
    sharp(inputPath).resize(500, null, { withoutEnlargement: true }).jpeg({ quality: 85 }).toFile(mediumPath),
    sharp(inputPath).jpeg({ quality: 90 }).toFile(originalPath) // re-saved
      // at high quality, but NOT resized - preserving the original's
      // actual dimensions while still compressing the file size somewhat
  ]);

  return { thumbnail: thumbnailPath, medium: mediumPath, original: originalPath };
}

