Validating a file's GENUINE type by reading its actual binary signature,
not merely trusting its claimed extension or Content-Type header:

import { fileTypeFromFile } from 'file-type';

async function validateGenuineFileType(filePath: string, allowedTypes: string[]): Promise<boolean> {
  const detectedType = await fileTypeFromFile(filePath);
  if (!detectedType) return false; // couldn't even determine a genuine type
  return allowedTypes.includes(detectedType.mime);
}

app.post('/profile/avatar', upload.single('avatar'), async (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'No file provided' });
    }

    const isValidType = await validateGenuineFileType(req.file.path, ['image/jpeg', 'image/png']);
    if (!isValidType) {
      return res.status(400).json({ success: false, error: 'File must be a genuine JPEG or PNG image' });
    }

    // ... proceed with lesson 4's processing and lesson 2/3's storage ...
  } catch (err) {
    next(err);
  }
});

