import multer from 'multer';
import { fileTypeFromFile } from 'file-type';
import fs from 'fs';

// LAYER 1 - size limit, enforced before the file is even fully
// received, preventing resource exhaustion from oversized uploads
const upload = multer({
  dest: 'uploads/',
  limits: { fileSize: 5 * 1024 * 1024 }
});

const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp'];

app.post('/products/:id/image', requireAuth, upload.single('image'), async (req, res, next) => {
  let tempFilePath: string | undefined;

  try {
    // LAYER 2 - confirm a file was genuinely provided at all
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'An image file is required' });
    }
    tempFilePath = req.file.path;

    // LAYER 3 - validate the file's GENUINE type by reading its
    // actual binary signature, never trusting the claimed extension
    // or Content-Type header alone
    const detectedType = await fileTypeFromFile(tempFilePath);
    if (!detectedType || !ALLOWED_TYPES.includes(detectedType.mime)) {
      fs.unlinkSync(tempFilePath); // clean up the rejected file
        // immediately, never leaving an unvalidated file lingering
      return res.status(400).json({
        success: false,
        error: 'File must be a genuine JPEG, PNG, or WebP image'
      });
    }

    // LAYER 4 - authorization check (Module 9's ownership pattern),
    // confirming this user genuinely has permission to modify this
    // specific product, before any file genuinely reaches permanent storage
    const product = await productsCollection.findOne({ _id: new ObjectId(req.params.id) });
    if (product.ownerId.toString() !== req.userId) {
      fs.unlinkSync(tempFilePath);
      return res.status(403).json({ success: false, error: 'Not authorized' });
    }

    // Only now, after ALL FOUR layers have genuinely passed, does
    // processing (lesson 4) and durable storage (lesson 2/3) proceed
    const processed = await processUploadedImage(tempFilePath, 'processed', `product-${req.params.id}`);
    const url = await uploadToCloudinaryOrS3(processed.medium);

    fs.unlinkSync(tempFilePath); // clean up the now fully-processed,
                                    // durably-stored temporary file

    res.json({ success: true, data: { imageUrl: url } });
  } catch (err) {
    if (tempFilePath && fs.existsSync(tempFilePath)) fs.unlinkSync(tempFilePath);
    next(err);
  }
});

