import multer from 'multer';
import { fileTypeFromFile } from 'file-type';
import fs from 'fs';

const upload = multer({ dest: 'uploads/', limits: { fileSize: 10 * 1024 * 1024 } });

app.post('/reports/:id/attachment', requireAuth, upload.single('attachment'), async (req, res, next) => {
  let tempFilePath: string | undefined;

  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'An attachment file is required' });
    }
    tempFilePath = req.file.path;

    const detectedType = await fileTypeFromFile(tempFilePath);
    if (!detectedType || detectedType.mime !== 'application/pdf') {
      fs.unlinkSync(tempFilePath);
      return res.status(400).json({ success: false, error: 'File must be a genuine PDF' });
    }

    const report = await reportsCollection.findOne({ _id: new ObjectId(req.params.id) });
    if (report.ownerId.toString() !== req.userId) {
      fs.unlinkSync(tempFilePath);
      return res.status(403).json({ success: false, error: 'Not authorized' });
    }

    // proceed with storage (lesson 2/3)
    fs.unlinkSync(tempFilePath);
    res.json({ success: true, data: { message: 'Attachment uploaded' } });
  } catch (err) {
    if (tempFilePath && fs.existsSync(tempFilePath)) fs.unlinkSync(tempFilePath);
    next(err);
  }
});

