// Immediate response - the user does NOT wait for processing or
// storage to genuinely complete
app.post('/photos', requireAuth, upload.single('photo'), async (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ success: false, error: 'A photo is required' });
    }

    const photoId = await photosCollection.insertOne({
      userId: req.userId,
      status: 'processing', // genuinely not ready yet - the frontend
                              // can poll or listen for this to change
      createdAt: new Date()
    });

    // Queue the ACTUAL work to run separately, AFTER this response
    // has already been sent - the user is not kept waiting
    processPhotoInBackground(req.file.path, photoId.insertedId.toString());

    res.status(202).json({ // 202 Accepted - genuinely different from
      // 200/201, signaling 'received, but not yet fully complete'
      success: true,
      data: { photoId: photoId.insertedId, status: 'processing' }
    });
  } catch (err) {
    next(err);
  }
});

// The actual, potentially lengthy work, running independently of any
// specific HTTP request/response cycle
async function processPhotoInBackground(localPath: string, photoId: string) {
  try {
    const processed = await processUploadedImage(localPath, 'processed', photoId);
    const urls = await Promise.all([
      uploadToS3(processed.thumbnail, `photos/${photoId}/thumb.jpg`),
      uploadToS3(processed.medium, `photos/${photoId}/medium.jpg`),
      uploadToS3(processed.original, `photos/${photoId}/original.jpg`)
    ]);

    await photosCollection.updateOne(
      { _id: new ObjectId(photoId) },
      { $set: { status: 'ready', urls } }
    );
  } catch (err) {
    await photosCollection.updateOne(
      { _id: new ObjectId(photoId) },
      { $set: { status: 'failed' } }
    );
  }
}
